css:
.fx-stf{width:min(1000px,100%)}
.fx-stf .hint{opacity:.5;font-size:.85em;text-align:center;padding:2em 0}
.fx-stf .run{height:260vh;position:relative}
.fx-stf .pin{position:sticky;top:0;height:100vh;display:grid;align-content:center;gap:1.4em}
.fx-stf .k{font-size:.78em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}
.fx-stf p.big{font:600 clamp(1.7em,4.6vw,3.2em)/1.18 var(--font-heading);letter-spacing:-.01em;max-width:22ch}
.fx-stf .w{opacity:.16;transition:opacity calc(.25s/var(--speed)) linear,color calc(.25s/var(--speed)) linear}
.fx-stf .w.on{opacity:1}.fx-stf .w.em.on{color:var(--accent)}
.fx-stf .meter{height:3px;background:var(--border);border-radius:3px;max-width:22ch;overflow:hidden}
.fx-stf .meter i{display:block;height:100%;background:var(--primary);transform-origin:left;transform:scaleX(var(--p,0))}
@media(prefers-reduced-motion:reduce){.fx-stf .w{opacity:1;transition:none}.fx-stf .w.em{color:var(--accent)}.fx-stf .meter{display:none}}

js:
(function(){var root=document.querySelector('.fx-stf'),run=root.querySelector('.run'),big=root.querySelector('[data-stf]'),mt=root.querySelector('.meter i'),tk=false;
(function split(n){Array.prototype.slice.call(n.childNodes).forEach(function(c){if(c.nodeType===3){var f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(function(t){if(!t)return;if(/^\s+$/.test(t)){f.appendChild(document.createTextNode(t));return}var s=document.createElement('span');s.className='w'+(n.classList&&n.classList.contains('em')?' em':'');s.textContent=t;f.appendChild(s)});n.replaceChild(f,c)}else if(c.nodeType===1)split(c)})})(big);
var ws=big.querySelectorAll('.w');
function upd(){tk=false;var r=run.getBoundingClientRect(),h=r.height-innerHeight,p=h>0?Math.min(1,Math.max(0,-r.top/h)):1;
mt.style.setProperty('--p',p);var n=Math.round(p*1.1*ws.length);ws.forEach(function(w,i){w.classList.toggle('on',i<n)})}
function req(){if(!tk){tk=true;requestAnimationFrame(upd)}}addEventListener('scroll',req,{passive:true});addEventListener('resize',req);upd()})();
